const { getOmedaSubscriptionIds, getPromoCodeFor } = require('@mindful-web/marko-web-omeda-identity-x/omeda-data');
const buildSubscriptionEntity = require('@mindful-web/marko-web-identity-x/utils/build-subscription-entity');

/**
 * Behavior config is now mandatory and can be generated by the CLI.
 * @see https://github.com/parameter1/identity-x-omeda-cli
 */
const behaviors = {
  logIn: 103,
  verifyEmail: 104,
  submitProfile: 105,
};

module.exports = (args) => {
  const {
    omedaConfig,
    idxConfig,
    rapidIdentProductId,
    websiteBehaviorAttributeId,
    // Passed through, if specified.
    appendPromoCodeToHook = [],
    appendBehaviorToHook = [],
    appendDemographicToHook = [],
    omedaPromoCodePrefix,
    omedaPromoCodeDefault,
    // A metered gate registration is a paywall unlock, not a newsletter opt-in, so the configured
    // auto-subscriptions are skipped for it by default. Sites opt back in by passing `false`.
    skipOptInsForMeteredGate = true,
    shouldAwait = {
      onLoginLinkSent: true,
    },
  } = args;

  // Both metered entry points stamp `contentGateType: 'metered'` into the event data: the meter
  // block's own login form, and the meter's step-2 profile form (which reports a `contentGate`
  // action source, so the source alone cannot identify it).
  const skipsMeteredOptIns = (additionalEventData = {}) => Boolean(
    skipOptInsForMeteredGate && additionalEventData.contentGateType === 'metered',
  );

  return {
    clientKey: omedaConfig.clientKey,
    brandKey: omedaConfig.brandKey,
    appId: omedaConfig.appId,
    inputId: omedaConfig.inputId,
    rapidIdentProductId,
    idxConfig,
    omedaPromoCodePrefix,
    omedaPromoCodeDefault,
    shouldAwait,
    behaviors,
    behaviorAttributes: {
      website: {
        id: 8,
        valueId: websiteBehaviorAttributeId,
      },
      actionSource: {
        id: 11,
        valueIds: {
          default: 199623,
          newsletterSignup: 199625,
          comments: 199626,
          contentGate: 199620,
        },
      },
      newsletterSignupType: {
        id: 9,
        valueIds: {
          default: 199617,
          pushdown: 199616,
          inlineContent: 199621,
          inlineSection: 199619,
          footer: 199615,
        },
      },
      contentGateType: {
        id: 10,
        valueIds: {
          default: 199618,
          metered: 199622,
          printPreview: 199624,
        },
      },
    },
    appendPromoCodeToHook,
    appendBehaviorToHook,
    appendDemographicToHook,
    onLoginLinkSentFormatter: (async ({
      req,
      payload: data,
      source: loginSource,
      additionalEventData = {},
      user,
    }) => {
      const payload = { ...data, user };

      const { requiresUserInput } = additionalEventData;
      if (requiresUserInput && behaviors.submitProfile) {
        payload.appendBehaviors = [
          ...(payload.appendBehaviors || []),
          {
            behaviorId: behaviors.submitProfile,
            attributes: payload.behavior && payload.behavior.attributes,
          },
        ];
      }

      // BAIL if omedaGraphQLCLient isnt available return payload.
      if (!req.$omedaGraphQLClient) return payload;

      const promoCode = getPromoCodeFor({
        loginSource,
        data: additionalEventData,
        defaultPromoCode: omedaPromoCodeDefault,
        promoCodePrefix: omedaPromoCodePrefix,
        req,
      });

      payload.promoCode = promoCode;
      payload.appendPromoCodes = [{ promoCode }];

      /** @type {OIDXOptInHooks} */
      const identityXOptInHooks = req.app.locals.site.getAsObject('identityXOptInHooks') || {};
      if (skipsMeteredOptIns(additionalEventData) || !identityXOptInHooks.onLoginLinkSent) {
        return payload;
      }

      // Append automatic product subscriptions and deployment opt-ins to OIDX payload
      const {
        demographics,
        deploymentTypeIds,
        productIds,
      } = identityXOptInHooks.onLoginLinkSent || {};

      // const { user } = payload;

      // Use original payload data to avoid altering user record on lookup.
      const {
        userProductIds,
        userDemoIds,
        userDeploymentIds,
      } = (!requiresUserInput)
        ? await getOmedaSubscriptionIds({ req, payload: data })
        : { userProductIds: new Set(), userDemoIds: new Set(), userDeploymentIds: new Set() };

      // Add demos, subscriptions, and opt-ins, excluding any the customer already has
      payload.appendDemographics = (demographics || []).reduce((arr, demo) => {
        if (userDemoIds.has(demo.id)) return arr;
        arr.push({
          demographicId: demo.id,
          valueIds: demo.valueIds || [],
          writeInValue: demo.writeInValue,
        });
        return arr;
      }, []);

      payload.appendSubscriptions = (productIds || []).reduce((arr, value) => {
        const {
          id,
          receive = true,
          requestedVersion,
        } = (typeof value === 'object') ? value : { id: value, receive: true };
        if (userProductIds.has(id)) return arr;
        arr.push({ id, receive, ...(requestedVersion && { requestedVersion }) });
        return arr;
      }, []);

      payload.deploymentTypes = (deploymentTypeIds || []).reduce((arr, id) => {
        if (userDeploymentIds.has(id)) return arr;
        arr.push({ id, optedIn: true });
        return arr;
      }, []);

      const { newsletterSignupType } = additionalEventData;
      // eslint-disable-next-line no-param-reassign
      additionalEventData.autoSignups = payload.deploymentTypes.map(({ id }) => ({
        userId: user.id,
        productId: id,
        promoCode,
        actionSource: loginSource,
        ...(newsletterSignupType && { newsletterSignupType }),
        subscriptionEntity: buildSubscriptionEntity({
          provider: 'omeda',
          tenant: omedaConfig.brandKey,
          type: 'product',
          identifier: id,
        }),
      }));
      return payload;
    }),
    // Profile updates otherwise fall through to the package's passthrough formatter, so the
    // rapid-identify payload carries no promo attribution and any configured appends would be
    // pushed without checking what the customer already has. Appends come from
    // `identityXOptInHooks.onUserProfileUpdate` and are deduped against the live Omeda record,
    // exactly like the login formatter above.
    onUserProfileUpdateFormatter: (async ({
      req,
      actionSource: loginSource,
      payload: data,
      additionalEventData = {},
    }) => {
      const { user } = data;
      const payload = { ...data };
      // BAIL if omedaGraphQLClient isn't available; return payload.
      if (!req.$omedaGraphQLClient) return payload;

      const promoCode = getPromoCodeFor({
        loginSource,
        data: additionalEventData,
        defaultPromoCode: omedaPromoCodeDefault,
        promoCodePrefix: omedaPromoCodePrefix,
        req,
      });

      payload.promoCode = promoCode;
      payload.appendPromoCodes = [{ promoCode }];

      /** @type {OIDXOptInHooks} */
      const identityXOptInHooks = req.app.locals.site.getAsObject('identityXOptInHooks') || {};
      if (skipsMeteredOptIns(additionalEventData) || !identityXOptInHooks.onUserProfileUpdate) {
        return payload;
      }

      const {
        demographics,
        deploymentTypeIds,
        productIds,
      } = identityXOptInHooks.onUserProfileUpdate || {};

      // Use original payload data to avoid altering the user record on lookup.
      const {
        userProductIds,
        userDemoIds,
        userDeploymentIds,
      } = await getOmedaSubscriptionIds({ req, payload: data });

      // Add demos, subscriptions and opt-ins, excluding any the customer already has.
      payload.appendDemographics = (demographics || []).reduce((arr, demo) => {
        if (userDemoIds.has(demo.id)) return arr;
        arr.push({
          demographicId: demo.id,
          valueIds: demo.valueIds || [],
          writeInValue: demo.writeInValue,
        });
        return arr;
      }, []);

      payload.appendSubscriptions = (productIds || []).reduce((arr, value) => {
        const {
          id,
          receive = true,
          requestedVersion,
        } = (typeof value === 'object') ? value : { id: value, receive: true };
        if (userProductIds.has(id)) return arr;
        arr.push({ id, receive, ...(requestedVersion && { requestedVersion }) });
        return arr;
      }, []);

      payload.deploymentTypes = (deploymentTypeIds || []).reduce((arr, id) => {
        if (userDeploymentIds.has(id)) return arr;
        arr.push({ id, optedIn: true });
        return arr;
      }, []);

      const { newsletterSignupType } = additionalEventData;
      // eslint-disable-next-line no-param-reassign
      additionalEventData.autoSignups = payload.deploymentTypes.map(({ id }) => ({
        userId: user.id,
        productId: id,
        promoCode,
        actionSource: loginSource,
        ...(newsletterSignupType && { newsletterSignupType }),
        subscriptionEntity: buildSubscriptionEntity({
          provider: 'omeda',
          tenant: omedaConfig.brandKey,
          type: 'product',
          identifier: id,
        }),
      }));
      return payload;
    }),
  };
};
